        }
        m_max_cached_index++;
    }
    SetRangeEnd(new_range_end);
    batch.WriteDescriptor(GetID(), m_wallet_descriptor);

    // By this point, the cache size should be the size of the entire range
    assert(m_wallet_descriptor.GetEnd() - 1 == m_max_cached_index);

