        return false;
    }
    if (IsAddressPreviouslySpent(dest)) {
        return true;
    }

    LegacyScriptPubKeyMan* spk_man = GetLegacyScriptPubKeyMan();
    if (!spk_man) return false;

    for (const auto& keyid : GetAffectedKeys(scriptPubKey, *spk_man)) {
        WitnessV0KeyHash wpkh_dest(keyid);
