        ScriptHash sh_wpkh_dest(GetScriptForDestination(wpkh_dest));
        if (IsAddressPreviouslySpent(sh_wpkh_dest)) {
            return true;
        }
        PKHash pkh_dest(keyid);
        if (IsAddressPreviouslySpent(pkh_dest)) {
            return true;
        }
    }
    return false;
}

