    //   - nTx: so that LoadBlockIndex() loads assumed-valid CBlockIndex entries
    //       (among other things)
    //   - nStatus & BLOCK_OPT_WITNESS: so that RewindBlockIndex() doesn't zealously
    //       unwind the assumed-valid chain.
    //
    CBlockIndex* index = nullptr;
